const input = $input.first()?.json || {};
const workflowName = input.workflow?.name || 'unknown-workflow';
const executionId = String(input.execution?.id || Date.now());
const failedNode = input.node?.name || input.lastNodeExecuted || 'unknown-node';
const message = input.error?.message || input.error?.description || 'Unhandled workflow error';
const timestamp = new Date().toISOString();
return [{
  json: {
    workflowName,
    executionId,
    failedNode,
    timestamp,
    details: message,
    status: 'failed'
  }
}];
